package main

import (
	"fmt"
	"os"
	"path/filepath"
)

const (
	helpText    = "Usage: elfcat <filename>\nWrites <filename>.html to CWD.\n"
	versionText = "elfcat 0.1.10\n"
)

func main() {
	os.Exit(run(os.Args))
}

func run(args []string) int {
	if len(args) == 2 {
		switch args[1] {
		case "-h", "--help":
			fmt.Print(helpText)
			return 0
		case "--version":
			fmt.Print(versionText)
			return 0
		}
	}

	if len(args) != 2 {
		fmt.Print(helpText)
		return 1
	}

	inputPath := args[1]

	data, err := os.ReadFile(inputPath)
	if err != nil {
		fmt.Printf("Failed to read file %q: %v\n", inputPath, err)
		return 1
	}

	ef, err := ParseELF(data)
	if err != nil {
		fmt.Printf("Failed to parse ELF: %v\n", err)
		return 1
	}

	report := GenerateHTML(ef, inputPath, filepath.Base(inputPath))
	outputPath := filepath.Base(inputPath) + ".html"
	if err := os.WriteFile(outputPath, []byte(report), 0o644); err != nil {
		fmt.Printf("Failed to write file %q: %v\n", outputPath, err)
		return 1
	}

	return 0
}

