package main

import (
	"debug/elf"
	"fmt"
	"strings"
)

func escapeHTML(s string) string {
	replacer := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		`"`, "&quot;",
		"'", "&apos;",
	)
	return replacer.Replace(s)
}

func className(c uint8) string {
	switch elf.Class(c) {
	case elf.ELFCLASS32:
		return "32-bit"
	case elf.ELFCLASS64:
		return "64-bit"
	default:
		return fmt.Sprintf("0x%x", c)
	}
}

func dataName(d uint8) string {
	switch elf.Data(d) {
	case elf.ELFDATA2LSB:
		return "Little endian"
	case elf.ELFDATA2MSB:
		return "Big endian"
	default:
		return fmt.Sprintf("0x%x", d)
	}
}

func abiName(abi uint8) string {
	switch abi {
	case 0:
		return "SysV"
	case 1:
		return "HP-UX"
	case 2:
		return "NetBSD"
	case 3:
		return "Linux"
	case 6:
		return "Solaris"
	case 7:
		return "AIX"
	case 8:
		return "IRIX"
	case 9:
		return "FreeBSD"
	case 10:
		return "TRU64"
	case 11:
		return "Novell Modesto"
	case 12:
		return "OpenBSD"
	case 13:
		return "OpenVMS"
	case 14:
		return "NonStop Kernel"
	case 15:
		return "AROS"
	case 16:
		return "Fenix OS"
	case 17:
		return "CloudABI"
	case 18:
		return "OpenVOS"
	default:
		return fmt.Sprintf("0x%x", abi)
	}
}

func fileTypeName(t uint16) string {
	switch elf.Type(t) {
	case elf.ET_NONE:
		return "No file type (NONE)"
	case elf.ET_REL:
		return "Relocatable object file (REL)"
	case elf.ET_EXEC:
		return "Executable file (EXEC)"
	case elf.ET_DYN:
		return "Shared object file (DYN)"
	case elf.ET_CORE:
		return "Core file (CORE)"
	default:
		return fmt.Sprintf("0x%x", t)
	}
}

func machineName(m uint16) string {
	switch elf.Machine(m) {
	case elf.EM_NONE:
		return "None"
	case elf.EM_386:
		return "x86"
	case elf.EM_X86_64:
		return "x86-64"
	case elf.EM_ARM:
		return "ARM"
	case elf.EM_AARCH64:
		return "AArch64"
	case elf.EM_MIPS:
		return "MIPS"
	case elf.EM_PPC:
		return "PowerPC"
	case elf.EM_PPC64:
		return "PowerPC64"
	case elf.EM_RISCV:
		return "RISC-V"
	case elf.EM_S390:
		return "IBM S/390"
	case elf.EM_SPARC:
		return "SPARC"
	case elf.EM_IA_64:
		return "IA-64"
	default:
		return fmt.Sprintf("0x%x", m)
	}
}

func programTypeName(t uint32) string {
	switch elf.ProgType(t) {
	case elf.PT_NULL:
		return "NULL"
	case elf.PT_LOAD:
		return "LOAD"
	case elf.PT_DYNAMIC:
		return "DYNAMIC"
	case elf.PT_INTERP:
		return "INTERP"
	case elf.PT_NOTE:
		return "NOTE"
	case elf.PT_SHLIB:
		return "SHLIB"
	case elf.PT_PHDR:
		return "PHDR"
	case elf.PT_TLS:
		return "TLS"
	case elf.PT_GNU_EH_FRAME:
		return "GNU_EH_FRAME (OS-specific)"
	case elf.PT_GNU_STACK:
		return "GNU_STACK (OS-specific)"
	case elf.PT_GNU_RELRO:
		return "GNU_RELRO (OS-specific)"
	default:
		if t >= 0x60000000 && t <= 0x6fffffff {
			return fmt.Sprintf("0x%x (OS-specific)", t)
		}
		if t >= 0x70000000 && t <= 0x7fffffff {
			return fmt.Sprintf("0x%x (Processor-specific)", t)
		}
		return fmt.Sprintf("0x%x", t)
	}
}

func sectionTypeName(t uint32) string {
	switch elf.SectionType(t) {
	case elf.SHT_NULL:
		return "NULL"
	case elf.SHT_PROGBITS:
		return "PROGBITS"
	case elf.SHT_SYMTAB:
		return "SYMTAB"
	case elf.SHT_STRTAB:
		return "STRTAB"
	case elf.SHT_RELA:
		return "RELA"
	case elf.SHT_HASH:
		return "HASH"
	case elf.SHT_DYNAMIC:
		return "DYNAMIC"
	case elf.SHT_NOTE:
		return "NOTE"
	case elf.SHT_NOBITS:
		return "NOBITS"
	case elf.SHT_REL:
		return "REL"
	case elf.SHT_SHLIB:
		return "SHLIB"
	case elf.SHT_DYNSYM:
		return "DYNSYM"
	case elf.SHT_INIT_ARRAY:
		return "INIT_ARRAY"
	case elf.SHT_FINI_ARRAY:
		return "FINI_ARRAY"
	case elf.SHT_PREINIT_ARRAY:
		return "PREINIT_ARRAY"
	case elf.SHT_GROUP:
		return "GROUP"
	case elf.SHT_SYMTAB_SHNDX:
		return "SYMTAB SECTION INDICES"
	default:
		switch t {
		case 0x6ffffff6:
			return "GNU_HASH (OS-specific)"
		case 0x6ffffffd:
			return "AUXILIARY (OS-specific)"
		case 0x6ffffffe:
			return "VER_NEED (OS-specific)"
		case 0x6fffffff:
			return "HIOS"
		case 0x6ffffffc:
			return "VER_DEF (OS-specific)"
		case 0x6ffffff0:
			return "VERSYM (OS-specific)"
		}
		if t >= 0x60000000 && t <= 0x6fffffff {
			return fmt.Sprintf("0x%x (OS-specific)", t)
		}
		if t >= 0x70000000 && t <= 0x7fffffff {
			return fmt.Sprintf("0x%x (Processor-specific)", t)
		}
		return fmt.Sprintf("0x%x", t)
	}
}

func programFlagsString(flags uint32) string {
	var b strings.Builder
	if flags&uint32(elf.PF_R) != 0 {
		b.WriteByte('R')
	}
	if flags&uint32(elf.PF_W) != 0 {
		b.WriteByte('W')
	}
	if flags&uint32(elf.PF_X) != 0 {
		b.WriteByte('X')
	}
	if b.Len() == 0 {
		return "0"
	}
	return b.String()
}

func sectionFlagsString(flags uint64) string {
	type flagDef struct {
		mask uint64
		ch   byte
	}
	defs := []flagDef{
		{0x1, 'W'},
		{0x2, 'A'},
		{0x4, 'X'},
		{0x10, 'M'},
		{0x20, 'S'},
		{0x40, 'I'},
		{0x80, 'L'},
		{0x100, 'O'},
		{0x200, 'G'},
		{0x400, 'T'},
		{0x800, 'C'},
		{0x80000000, 'E'},
	}

	var b strings.Builder
	for _, def := range defs {
		if flags&def.mask != 0 {
			b.WriteByte(def.ch)
		}
	}
	if b.Len() == 0 {
		return "0"
	}
	return b.String()
}

func formatSummaryFileSize(size uint64) string {
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}
	return fmt.Sprintf("%s (%d B)", humanizeBinary(size), size)
}

func formatDataSize(size uint64) string {
	if size < 1024 {
		return fmt.Sprintf("%d", size)
	}
	return fmt.Sprintf("%d (%s)", size, humanizeBinary(size))
}

func humanizeBinary(size uint64) string {
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	value := float64(size)
	unit := 0
	for value >= 1024 && unit < len(units)-1 {
		value /= 1024
		unit++
	}
	return fmt.Sprintf("%.1f %s", value/1024, units[unit])
}

func hexValue(v uint64) string {
	return fmt.Sprintf("0x%x", v)
}

func decNumberSpan(v uint64) string {
	return fmt.Sprintf("<span class='number' title='%s'>%d</span>", hexValue(v), v)
}

func decNumberSpanClass(v uint64, class string) string {
	return fmt.Sprintf("<span title='%s' class='number %s'>%d</span>", hexValue(v), class, v)
}

func hexNumberSpan(v uint64) string {
	return fmt.Sprintf("<span class='number' title='%d'>%s</span>", v, hexValue(v))
}

func dataSizeSpan(v uint64) string {
	return fmt.Sprintf("<span class='number' title='%s'>%s</span>", hexValue(v), formatDataSize(v))
}

func stringTableEntries(data []byte) []string {
	entries := make([]string, 0)
	start := 0
	for i, b := range data {
		if b != 0 {
			continue
		}
		if i > start {
			entries = append(entries, string(data[start:i]))
		}
		start = i + 1
	}
	if start < len(data) {
		entries = append(entries, string(data[start:]))
	}
	return entries
}

func asciiByte(b byte) string {
	if b < 0x20 || b > 0x7e {
		return "."
	}
	switch b {
	case '&':
		return "&amp;"
	case '<':
		return "&lt;"
	case '>':
		return "&gt;"
	case '"':
		return "&quot;"
	case '\'':
		return "&apos;"
	default:
		return string(b)
	}
}

