+func writeFileInfoTable(b *strings.Builder, ef *ELFFile, inputPath string) {
+	b.WriteString("    <table>\n")
+	b.WriteString("      <tr class='fileinfo_file_name'> <td>File name:</td> <td>")
+	b.WriteString(escapeHTML(inputPath))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_file_size'> <td>File size:</td> <td>")
+	b.WriteString(formatSummaryFileSize(uint64(len(ef.Bytes))))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_class'> <td>Object class:</td> <td>")
+	b.WriteString(className(ef.Class))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>")
+	b.WriteString(dataName(ef.Data))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_abi'> <td>ABI:</td> <td>")
+	b.WriteString(abiName(ef.Bytes[7]))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_e_type'> <td>Type:</td> <td>")
+	b.WriteString(fileTypeName(ef.Header.Type))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_e_machine'> <td>Architecture:</td> <td>")
+	b.WriteString(machineName(ef.Header.Machine))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_e_entry'> <td>Entrypoint:</td> <td>")
+	b.WriteString(hexNumberSpan(ef.Header.Entry))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_ph'> <td>Program headers:</td> <td>")
+	b.WriteString(decNumberSpanClass(uint64(ef.Header.Phnum), "fileinfo_e_phnum"))
+	b.WriteString(" * ")
+	b.WriteString(decNumberSpanClass(uint64(ef.Header.Phentsize), "fileinfo_e_phentsize"))
+	b.WriteString(" @ ")
+	b.WriteString(decNumberSpanClass(ef.Header.Phoff, "fileinfo_e_phoff"))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("      <tr class='fileinfo_sh'> <td>Section headers:</td> <td>")
+	b.WriteString(decNumberSpanClass(uint64(ef.Header.Shnum), "fileinfo_e_shnum"))
+	b.WriteString(" * ")
+	b.WriteString(decNumberSpanClass(uint64(ef.Header.Shentsize), "fileinfo_e_shentsize"))
+	b.WriteString(" @ ")
+	b.WriteString(decNumberSpanClass(ef.Header.Shoff, "fileinfo_e_shoff"))
+	b.WriteString("</td> </tr>\n")
+	b.WriteString("    </table>\n")
+}
+
+func renderOffsets(fileLen int) string {
+	var b strings.Builder
+	for off := 0; off < fileLen; off += 16 {
+		if off > 0 {
+			b.WriteByte('\n')
+		}
+		b.WriteString(fmt.Sprintf("%x", off))
+	}
+	return b.String()
+}
+
+func renderBytes(ef *ELFFile) string {
+	starts, ends := buildSpanEvents(ef)
+	var b strings.Builder
+	for i := 0; i < len(ef.Bytes); i++ {
+		for _, tag := range starts[i] {
+			b.WriteString(tag)
+		}
+		b.WriteString(byteToken(ef.Bytes, i))
+		for j := 0; j < ends[i+1]; j++ {
+			b.WriteString("</span>")
+		}
+		if i+1 == len(ef.Bytes) {
+			continue
+		}
+		if i%16 == 15 {
+			b.WriteByte('\n')
+		} else {
+			b.WriteByte(' ')
+		}
+	}
+	return b.String()
+}
+
+func renderASCII(data []byte) string {
+	var b strings.Builder
+	for i, by := range data {
+		b.WriteString(asciiByte(by))
+		if i+1 == len(data) {
+			continue
+		}
+		if i%16 == 15 {
+			b.WriteByte('\n')
+		}
+	}
+	return b.String()
+}
+
+func buildSpanEvents(ef *ELFFile) (map[int][]string, map[int]int) {
+	starts := make(map[int][]string)
+	ends := make(map[int]int)
+	addSpan := func(start, end uint64, class string) {
+		if end <= start {
+			return
+		}
+		if start >= uint64(len(ef.Bytes)) {
+			return
+		}
+		if end > uint64(len(ef.Bytes)) {
+			return
+		}
+		starts[int(start)] = append(starts[int(start)], "<span class='"+class+"'>")
+		ends[int(end)]++
+	}
+
+	addSpan(0, ef.HeaderSize, "ehdr")
+	addSpan(0, 16, "ident")
+	addSpan(0, 4, "magic")
+	addSpan(4, 5, "class")
+	addSpan(5, 6, "data")
+	addSpan(6, 7, "ver")
+	addSpan(7, 8, "abi")
+	addSpan(8, 9, "abi_ver")
+	addSpan(9, 16, "pad")
+
+	if ef.Class == byte(elf.ELFCLASS32) {
+		addSpan(16, 18, "e_type")
+		addSpan(18, 20, "e_machine")
+		addSpan(20, 24, "e_version")
+		addSpan(24, 28, "e_entry")
+		addSpan(28, 32, "e_phoff")
+		addSpan(32, 36, "e_shoff")
+		addSpan(36, 40, "e_flags")
+		addSpan(40, 42, "e_ehsize")
+		addSpan(42, 44, "e_phentsize")
+		addSpan(44, 46, "e_phnum")
+		addSpan(46, 48, "e_shentsize")
+		addSpan(48, 50, "e_shnum")
+		addSpan(50, 52, "e_shstrndx")
+	} else {
+		addSpan(16, 18, "e_type")
+		addSpan(18, 20, "e_machine")
+		addSpan(20, 24, "e_version")
+		addSpan(24, 32, "e_entry")
+		addSpan(32, 40, "e_phoff")
+		addSpan(40, 48, "e_shoff")
+		addSpan(48, 52, "e_flags")
+		addSpan(52, 54, "e_ehsize")
+		addSpan(54, 56, "e_phentsize")
+		addSpan(56, 58, "e_phnum")
+		addSpan(58, 60, "e_shentsize")
+		addSpan(60, 62, "e_shnum")
+		addSpan(62, 64, "e_shstrndx")
+	}
+
+	for _, ph := range ef.Segments {
+		base := ef.Header.Phoff + uint64(ph.Index)*uint64(ef.Header.Phentsize)
+		addSpan(base, base+uint64(ef.Header.Phentsize), fmt.Sprintf("bin_phdr%d phdr", ph.Index))
+		if ef.Class == byte(elf.ELFCLASS32) {
+			addSpan(base, base+4, "p_type")
+			addSpan(base+4, base+8, "p_offset")
+			addSpan(base+8, base+12, "p_vaddr")
+			addSpan(base+12, base+16, "p_paddr")
+			addSpan(base+16, base+20, "p_filesz")
+			addSpan(base+20, base+24, "p_memsz")
+			addSpan(base+24, base+28, "p_flags")
+			addSpan(base+28, base+32, "p_align")
+		} else {
+			addSpan(base, base+4, "p_type")
+			addSpan(base+4, base+8, "p_flags")
+			addSpan(base+8, base+16, "p_offset")
+			addSpan(base+16, base+24, "p_vaddr")
+			addSpan(base+24, base+32, "p_paddr")
+			addSpan(base+32, base+40, "p_filesz")
+			addSpan(base+40, base+48, "p_memsz")
+			addSpan(base+48, base+56, "p_align")
+		}
+	}
+
+	for _, sh := range ef.Sections {
+		base := ef.Header.Shoff + uint64(sh.Index)*uint64(ef.Header.Shentsize)
+		addSpan(base, base+uint64(ef.Header.Shentsize), fmt.Sprintf("bin_shdr%d shdr", sh.Index))
+		if ef.Class == byte(elf.ELFCLASS32) {
+			addSpan(base, base+4, "sh_name")
+			addSpan(base+4, base+8, "sh_type")
+			addSpan(base+8, base+12, "sh_flags")
+			addSpan(base+12, base+16, "sh_addr")
+			addSpan(base+16, base+20, "sh_offset")
+			addSpan(base+20, base+24, "sh_size")
+			addSpan(base+24, base+28, "sh_link")
+			addSpan(base+28, base+32, "sh_info")
+			addSpan(base+32, base+36, "sh_addralign")
+			addSpan(base+36, base+40, "sh_entsize")
+		} else {
+			addSpan(base, base+4, "sh_name")
+			addSpan(base+4, base+8, "sh_type")
+			addSpan(base+8, base+16, "sh_flags")
+			addSpan(base+16, base+24, "sh_addr")
+			addSpan(base+24, base+32, "sh_offset")
+			addSpan(base+32, base+40, "sh_size")
+			addSpan(base+40, base+44, "sh_link")
+			addSpan(base+44, base+48, "sh_info")
+			addSpan(base+48, base+56, "sh_addralign")
+			addSpan(base+56, base+64, "sh_entsize")
+		}
+	}
+
+	for _, ph := range ef.Segments {
+		if !shouldRenderSegmentBytes(ef, ph) {
+			continue
+		}
+		addSpan(ph.Offset, ph.Offset+ph.Filesz, fmt.Sprintf("bin_segment%d segment", ph.Index))
+	}
+
+	for _, sh := range ef.Sections {
+		if !shouldRenderSectionBytes(ef, sh) {
+			continue
+		}
+		addSpan(sh.Offset, sh.Offset+sh.Size, fmt.Sprintf("bin_section%d section hover", sh.Index))
+	}
+
+	for _, ph := range ef.Segments {
+		if ph.Type != uint32(elf.PT_NOTE) || !shouldRenderSegmentBytes(ef, ph) {
+			continue
+		}
+		for _, sh := range ef.Sections {
+			if sh.Type != uint32(elf.SHT_NOTE) || !shouldRenderSectionBytes(ef, sh) {
+				continue
+			}
+			if sh.Offset >= ph.Offset && sh.Offset+sh.Size <= ph.Offset+ph.Filesz {
+				addSpan(sh.Offset, sh.Offset+sh.Size, "segment_subrange hover")
+			}
+		}
+	}
+
+	return starts, ends
+}
+
+func shouldRenderSegmentBytes(ef *ELFFile, ph ProgramHeader) bool {
+	if ph.Filesz == 0 {
+		return false
+	}
+	if ph.Type == uint32(elf.PT_LOAD) && ph.Offset == 0 {
+		return false
+	}
+	_, ok := sliceRange(ef.Bytes, ph.Offset, ph.Filesz)
+	return ok
+}
+
+func shouldRenderSectionBytes(ef *ELFFile, sh SectionHeader) bool {
+	if sh.Size == 0 {
+		return false
+	}
+	if sh.Type == uint32(elf.SHT_NOBITS) {
+		return false
+	}
+	_, ok := sliceRange(ef.Bytes, sh.Offset, sh.Size)
+	return ok
+}
+
+func byteToken(data []byte, off int) string {
+	if off == 0 {
+		return "7f"
+	}
+	if off > 0 && off < 4 {
+		return "&nbsp;" + string(data[off])
+	}
+	return fmt.Sprintf("%02x", data[off])
+}
+
+func writeStickyTable(b *strings.Builder, ef *ELFFile) {
+	b.WriteString("    <table id='sticky_table' cellspacing='0'>\n")
+	b.WriteString("      <tr>\n")
+	b.WriteString("        <td id='desc'></td>\n")
+	b.WriteString("        <td class='infotables'>\n")
+	for _, ph := range ef.Segments {
+		writeProgramHeaderTable(b, ph)
+	}
+	for _, sh := range ef.Sections {
+		writeSectionHeaderTable(b, sh)
+	}
+	b.WriteString("        </td>\n")
+	b.WriteString("        <td class='infotables'>\n")
+	for _, ph := range ef.Segments {
+		writeSegmentTable(b, ef, ph)
+	}
+	for _, sh := range ef.Sections {
+		writeSectionTable(b, ef, sh)
+	}
+	b.WriteString("        </td>\n")
+	b.WriteString("      </tr>\n")
+	b.WriteString("    </table>\n")
+}
+
+func writeProgramHeaderTable(b *strings.Builder, ph ProgramHeader) {
+	b.WriteString(fmt.Sprintf("          <table class='conceal itable' id='info_phdr%d'>\n", ph.Index))
+	b.WriteString("          <th colspan='2' class='phdr_itable'></th>\n")
+	b.WriteString("            <tr> <td>Type:</td> <td>" + escapeHTML(programTypeName(ph.Type)) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Flags:</td> <td>" + programFlagsString(ph.Flags) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Offset in file:</td> <td>" + hexNumberSpan(ph.Offset) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Size in file:</td> <td>" + dataSizeSpan(ph.Filesz) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Vaddr in memory:</td> <td>" + hexNumberSpan(ph.Vaddr) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Size in memory:</td> <td>" + dataSizeSpan(ph.Memsz) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Alignment:</td> <td>" + hexNumberSpan(ph.Align) + "</td> </tr>\n")
+	b.WriteString("          </table>\n")
+}
+
+func writeSectionHeaderTable(b *strings.Builder, sh SectionHeader) {
+	b.WriteString(fmt.Sprintf("          <table class='conceal itable' id='info_shdr%d'>\n", sh.Index))
+	b.WriteString("          <th colspan='2' class='shdr_itable'></th>\n")
+	b.WriteString(fmt.Sprintf("            <tr> <td>Index:</td> <td>%d</td> </tr>\n", sh.Index))
+	b.WriteString("            <tr> <td>Name:</td> <td>" + escapeHTML(sh.Name) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Type:</td> <td>" + escapeHTML(sectionTypeName(sh.Type)) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Flags:</td> <td>" + sectionFlagsString(sh.Flags) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Vaddr in memory:</td> <td>" + hexNumberSpan(sh.Addr) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Offset in file:</td> <td>" + hexNumberSpan(sh.Offset) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Size in file:</td> <td>" + dataSizeSpan(sh.Size) + "</td> </tr>\n")
+	b.WriteString(fmt.Sprintf("            <tr> <td>Linked section:</td> <td>%d</td> </tr>\n", sh.Link))
+	b.WriteString("            <tr> <td>Extra info:</td> <td>" + decNumberSpan(uint64(sh.Info)) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Alignment:</td> <td>" + hexNumberSpan(sh.Addralign) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Size of entries:</td> <td>" + dataSizeSpan(sh.Entsize) + "</td> </tr>\n")
+	b.WriteString("          </table>\n")
+}
+
+func writeSegmentTable(b *strings.Builder, ef *ELFFile, ph ProgramHeader) {
+	b.WriteString(fmt.Sprintf("          <table class='conceal itable' id='info_segment%d'>\n", ph.Index))
+	b.WriteString("          <th colspan='2' class='segment_itable'></th>\n")
+	b.WriteString("            <tr> <td>Type:</td> <td>" + escapeHTML(programTypeName(ph.Type)) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Size in file:</td> <td>" + dataSizeSpan(ph.Filesz) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Size in memory:</td> <td>" + dataSizeSpan(ph.Memsz) + "</td> </tr>\n")
+
+	if ph.Type == uint32(elf.PT_INTERP) {
+		if blob, ok := sliceRange(ef.Bytes, ph.Offset, ph.Filesz); ok {
+			b.WriteString("            <tr><td><br></td></tr>\n")
+			b.WriteString("            <tr> <td>Interpreter:</td> <td>")
+			b.WriteString(escapeHTML(trimCString(blob)))
+			b.WriteString("</td> </tr>\n")
+		}
+	} else if ph.Type == uint32(elf.PT_NOTE) && len(ph.NoteEntries) > 0 {
+		b.WriteString("            <tr><td><br></td></tr>\n")
+		for i, note := range ph.NoteEntries {
+			if i > 0 {
+				b.WriteString("            <tr> <td><br></td> </tr>\n")
+			}
+			b.WriteString("            <tr> <td>Name:</td> <td>")
+			b.WriteString(escapeHTML(note.Name))
+			b.WriteString("</td> </tr>\n")
+			b.WriteString(fmt.Sprintf("            <tr> <td>Type:</td> <td>0x%x</td> </tr>\n", note.Type))
+			if note.Name == "GNU" && note.Type == 3 {
+				b.WriteString("            <tr> <td>Build ID:</td> <td>")
+				for _, by := range note.Desc {
+					b.WriteString(fmt.Sprintf("%02x", by))
+				}
+				b.WriteString("</td> </tr>\n")
+			} else {
+				b.WriteString("            <tr> <td>Desc:</td> <td>")
+				for _, by := range note.Desc {
+					b.WriteString("<b>")
+					b.WriteString(fmt.Sprintf("%02x", by))
+					b.WriteString("</b> ")
+				}
+				b.WriteString("</td> </tr>\n")
+			}
+		}
+	}
+
+	b.WriteString("          </table>\n")
+}
+
+func writeSectionTable(b *strings.Builder, ef *ELFFile, sh SectionHeader) {
+	b.WriteString(fmt.Sprintf("          <table class='conceal itable' id='info_section%d'>\n", sh.Index))
+	b.WriteString("          <th colspan='2' class='section_itable'></th>\n")
+	b.WriteString("            <tr> <td>Type:</td> <td>" + escapeHTML(sectionTypeName(sh.Type)) + "</td> </tr>\n")
+	b.WriteString("            <tr> <td>Size:</td> <td>" + dataSizeSpan(sh.Size) + "</td> </tr>\n")
+
+	if sh.Type == uint32(elf.SHT_STRTAB) {
+		if blob, ok := ef.sectionData(sh); ok {
+			b.WriteString("            <tr><td><br></td></tr>\n")
+			b.WriteString("            <tr>\n")
+			b.WriteString("              <td></td>\n")
+			b.WriteString("              <td>\n")
+			b.WriteString("                <div>\n")
+			for _, entry := range stringTableEntries(blob) {
+				b.WriteString("                  ")
+				b.WriteString(escapeHTML(entry))
+				b.WriteString("\n")
+			}
+			b.WriteString("                </div>\n")
+			b.WriteString("              </td>\n")
+			b.WriteString("            </tr>\n")
+		}
+	}
+
+	b.WriteString("          </table>\n")
+}
+
+func writeHighlightScript(b *strings.Builder) {
+	b.WriteString(`    <script type='text/javascript'>
+      let color = "#ee9";
+
+      function addPairHighlighting(elem, depElem) {
+          elem.addEventListener("mouseenter", function(event) {
+              event.target.style.backgroundColor = color;
+              depElem.style.backgroundColor = color;
+          }, false);
+
+          elem.addEventListener("mouseleave", function(event) {
+              event.target.style.backgroundColor = "";
+              depElem.style.backgroundColor = "";
+          }, false);
+      }
+
+      function highlightClasses(primaryClass, secondaryClass) {
+          let primaryElems = document.getElementsByClassName(primaryClass);
+          let secondaryElems = document.getElementsByClassName(secondaryClass);
+
+          if (primaryElems.length === 0 || secondaryElems.length === 0) {
+              return;
+          }
+
+          let primaryElem = primaryElems[0];
+          let secondaryElem = secondaryElems[0];
+
+          addPairHighlighting(primaryElem, secondaryElem);
+          addPairHighlighting(secondaryElem, primaryElem);
+      }
+
+      highlightClasses('fileinfo_class', 'class')
+      highlightClasses('fileinfo_data', 'data')
