+func writeArrowsScript(b *strings.Builder, ef *ELFFile) {
+	b.WriteString(`    <script type='text/javascript'>
+      const arrows = document.getElementById('arrows');
+      let connections = [];
+      let batchElems = '';
+
+      function getAbsPosition(elem) {
+          let x = 0, y = 0;
+
+          do {
+              x += elem.offsetLeft || 0;
+              y += elem.offsetTop || 0;
+
+              elem = elem.offsetParent;
+          } while (elem);
+
+          return {
+              x: x,
+              y: y
+          };
+      }
+
+      function getBoundingBoxSizes(elem) {
+          let rect = elem.getBoundingClientRect();
+
+          return {
+              w: rect.width || elem.offsetWidth,
+              h: rect.height || elem.offsetHeight
+          };
+      }
