func GenerateHTML(ef *ELFFile, inputPath, baseName string) string {
	var b strings.Builder

	b.WriteString("<!doctype html>\n")
	b.WriteString("<html>\n")
	b.WriteString("  <head>\n")
	b.WriteString("    <meta charset='utf-8'>\n")
	b.WriteString("    <meta name='viewport' content='width=900, initial-scale=1'>\n")
	b.WriteString("    <title>")
	b.WriteString(escapeHTML(baseName))
	b.WriteString("</title>\n")
	b.WriteString(styleBlock())
	b.WriteString("  </head>\n")
	b.WriteString("  <body>\n")
	b.WriteString("    <svg width='100%' height='100%'>\n")
	b.WriteString("      <defs>\n")
	b.WriteString("        <marker id='arrowhead' viewBox='0 0 10 10' refX='10' refY='5' markerWidth='10' markerHeight='10' orient='auto'>\n")
	b.WriteString("          <path d='M 0 0 L 10 5 L 0 10 z' />\n")
	b.WriteString("        </marker>\n")
	b.WriteString("      </defs>\n")
	b.WriteString("      <g id='arrows' stroke='black' stroke-width='1' marker-end='url(#arrowhead)'></g>\n")
	b.WriteString("    </svg>\n")
	b.WriteString("    <div id='rightmenu'>\n")
	b.WriteString("      <a id='credits' href='https://github.com/rbakbashev/elfcat'>generated with elfcat 0.1.10</a>\n")
	b.WriteString("      <button class='textbutton' id='settings_toggle'>Settings</button>\n")
	b.WriteString("      <button class='textbutton' id='help_toggle'>Help</button>\n")
	b.WriteString("      <div class='right_hidden' id='settings'>\n")
	b.WriteString("        <label for='arrow_opacity_range'>Arrow opacity:</label>\n")
	b.WriteString("        <input type='range' id='arrow_opacity_range' min='0' max='100' value='100'>\n")
	b.WriteString("      </div>\n")
	b.WriteString("      <div class='right_hidden' id='help'>\n")
	b.WriteString("        <p>The leftmost column shows offsets within the file. The middle column is the file dump. It has ELF structs, sections and segments highlighted. Some fields that reference areas in the file are clickable and connected with arrows. The rightmost column shows printable ASCII characters corresponding to the file bytes.</p>\n")
	b.WriteString("        <p>Legend</p>\n")
	b.WriteString("        <ul>\n")
	b.WriteString("          <li><span class='legend_rect ident'></span>ELF Identification</li>\n")
	b.WriteString("          <li><span class='legend_rect ehdr'></span>ELF Header</li>\n")
	b.WriteString("          <li><span class='legend_rect phdr'></span>Program Header</li>\n")
	b.WriteString("          <li><span class='legend_rect shdr'></span>Section Header</li>\n")
	b.WriteString("          <li><span class='legend_rect segment'></span>Segment</li>\n")
	b.WriteString("          <li><span class='legend_rect section'></span>Section</li>\n")
	b.WriteString("          <li><span class='legend_rect segm_sect_legend'></span>Segment &amp; Section overlap</li>\n")
	b.WriteString("        </ul>\n")
	b.WriteString("      </div>\n")
	b.WriteString("    </div>\n")
	writeFileInfoTable(&b, ef, inputPath)
	b.WriteString("    <div id='offsets'>")
	b.WriteString(renderOffsets(len(ef.Bytes)))
	b.WriteString("</div>\n")
	b.WriteString("    <div id='bytes'>")
	b.WriteString(renderBytes(ef))
	b.WriteString("</div>\n")
	b.WriteString("    <div id='ascii'>")
	b.WriteString(renderASCII(ef.Bytes))
	b.WriteString("</div>\n")
	writeStickyTable(&b, ef)
	writeHighlightScript(&b)
	writeDescriptionsScript(&b)
	writeHoverTablesScript(&b)
	writeOffsetsScript(&b, len(ef.Bytes))
	writeArrowsScript(&b, ef)
	writeSettingsScript(&b)
	b.WriteString("  </body>\n")
	b.WriteString("</html>\n")

	return b.String()
}

