func renderOffsets(fileLen int) string {
	var b strings.Builder
	for off := 0; off < fileLen; off += 16 {
		if off > 0 {
			b.WriteByte('\n')
		}
		b.WriteString(fmt.Sprintf("%x", off))
	}
	return b.String()
}

func renderBytes(ef *ELFFile) string {
	starts, ends := buildSpanEvents(ef)
	var b strings.Builder
	for i := 0; i < len(ef.Bytes); i++ {
		for _, tag := range starts[i] {
			b.WriteString(tag)
		}
		b.WriteString(byteToken(ef.Bytes, i))
		for j := 0; j < ends[i+1]; j++ {
			b.WriteString("</span>")
		}
		if i+1 == len(ef.Bytes) {
			continue
		}
		if i%16 == 15 {
			b.WriteByte('\n')
		} else {
			b.WriteByte(' ')
		}
	}
	return b.String()
}

func renderASCII(data []byte) string {
	var b strings.Builder
	for i, by := range data {
		b.WriteString(asciiByte(by))
		if i+1 == len(data) {
			continue
		}
		if i%16 == 15 {
			b.WriteByte('\n')
		}
	}
	return b.String()
}

func buildSpanEvents(ef *ELFFile) (map[int][]string, map[int]int) {
	starts := make(map[int][]string)
	ends := make(map[int]int)
	addSpan := func(start, end uint64, class string) {
		if end <= start {
			return
		}
		if start >= uint64(len(ef.Bytes)) {
			return
		}
		if end > uint64(len(ef.Bytes)) {
			return
		}
		starts[int(start)] = append(starts[int(start)], "<span class='"+class+"'>")
		ends[int(end)]++
	}

	addSpan(0, ef.HeaderSize, "ehdr")
	addSpan(0, 16, "ident")
	addSpan(0, 4, "magic")
	addSpan(4, 5, "class")
	addSpan(5, 6, "data")
	addSpan(6, 7, "ver")
	addSpan(7, 8, "abi")
	addSpan(8, 9, "abi_ver")
	addSpan(9, 16, "pad")

	if ef.Class == byte(elf.ELFCLASS32) {
		addSpan(16, 18, "e_type")
		addSpan(18, 20, "e_machine")
		addSpan(20, 24, "e_version")
		addSpan(24, 28, "e_entry")
		addSpan(28, 32, "e_phoff")
		addSpan(32, 36, "e_shoff")
		addSpan(36, 40, "e_flags")
		addSpan(40, 42, "e_ehsize")
		addSpan(42, 44, "e_phentsize")
		addSpan(44, 46, "e_phnum")
		addSpan(46, 48, "e_shentsize")
		addSpan(48, 50, "e_shnum")
		addSpan(50, 52, "e_shstrndx")
	} else {
		addSpan(16, 18, "e_type")
		addSpan(18, 20, "e_machine")
		addSpan(20, 24, "e_version")
		addSpan(24, 32, "e_entry")
		addSpan(32, 40, "e_phoff")
		addSpan(40, 48, "e_shoff")
		addSpan(48, 52, "e_flags")
		addSpan(52, 54, "e_ehsize")
		addSpan(54, 56, "e_phentsize")
		addSpan(56, 58, "e_phnum")
		addSpan(58, 60, "e_shentsize")
		addSpan(60, 62, "e_shnum")
		addSpan(62, 64, "e_shstrndx")
	}

	for _, ph := range ef.Segments {
		base := ef.Header.Phoff + uint64(ph.Index)*uint64(ef.Header.Phentsize)
		addSpan(base, base+uint64(ef.Header.Phentsize), fmt.Sprintf("bin_phdr%d phdr", ph.Index))
		if ef.Class == byte(elf.ELFCLASS32) {
			addSpan(base, base+4, "p_type")
			addSpan(base+4, base+8, "p_offset")
			addSpan(base+8, base+12, "p_vaddr")
			addSpan(base+12, base+16, "p_paddr")
			addSpan(base+16, base+20, "p_filesz")
			addSpan(base+20, base+24, "p_memsz")
			addSpan(base+24, base+28, "p_flags")
			addSpan(base+28, base+32, "p_align")
		} else {
			addSpan(base, base+4, "p_type")
			addSpan(base+4, base+8, "p_flags")
			addSpan(base+8, base+16, "p_offset")
			addSpan(base+16, base+24, "p_vaddr")
			addSpan(base+24, base+32, "p_paddr")
			addSpan(base+32, base+40, "p_filesz")
			addSpan(base+40, base+48, "p_memsz")
			addSpan(base+48, base+56, "p_align")
		}
	}

	for _, sh := range ef.Sections {
		base := ef.Header.Shoff + uint64(sh.Index)*uint64(ef.Header.Shentsize)
		addSpan(base, base+uint64(ef.Header.Shentsize), fmt.Sprintf("bin_shdr%d shdr", sh.Index))
		if ef.Class == byte(elf.ELFCLASS32) {
			addSpan(base, base+4, "sh_name")
			addSpan(base+4, base+8, "sh_type")
			addSpan(base+8, base+12, "sh_flags")
			addSpan(base+12, base+16, "sh_addr")
			addSpan(base+16, base+20, "sh_offset")
			addSpan(base+20, base+24, "sh_size")
			addSpan(base+24, base+28, "sh_link")
			addSpan(base+28, base+32, "sh_info")
			addSpan(base+32, base+36, "sh_addralign")
			addSpan(base+36, base+40, "sh_entsize")
		} else {
			addSpan(base, base+4, "sh_name")
			addSpan(base+4, base+8, "sh_type")
			addSpan(base+8, base+16, "sh_flags")
			addSpan(base+16, base+24, "sh_addr")
			addSpan(base+24, base+32, "sh_offset")
			addSpan(base+32, base+40, "sh_size")
			addSpan(base+40, base+44, "sh_link")
			addSpan(base+44, base+48, "sh_info")
			addSpan(base+48, base+56, "sh_addralign")
			addSpan(base+56, base+64, "sh_entsize")
		}
	}

	for _, ph := range ef.Segments {
		if !shouldRenderSegmentBytes(ef, ph) {
			continue
		}
		addSpan(ph.Offset, ph.Offset+ph.Filesz, fmt.Sprintf("bin_segment%d segment", ph.Index))
	}

	for _, sh := range ef.Sections {
		if !shouldRenderSectionBytes(ef, sh) {
			continue
		}
		addSpan(sh.Offset, sh.Offset+sh.Size, fmt.Sprintf("bin_section%d section hover", sh.Index))
	}

	for _, ph := range ef.Segments {
		if ph.Type != uint32(elf.PT_NOTE) || !shouldRenderSegmentBytes(ef, ph) {
			continue
		}
		for _, sh := range ef.Sections {
			if sh.Type != uint32(elf.SHT_NOTE) || !shouldRenderSectionBytes(ef, sh) {
				continue
			}
			if sh.Offset >= ph.Offset && sh.Offset+sh.Size <= ph.Offset+ph.Filesz {
				addSpan(sh.Offset, sh.Offset+sh.Size, "segment_subrange hover")
			}
		}
	}

	return starts, ends
}

func shouldRenderSegmentBytes(ef *ELFFile, ph ProgramHeader) bool {
	if ph.Filesz == 0 {
		return false
	}
	if ph.Type == uint32(elf.PT_LOAD) && ph.Offset == 0 {
		return false
	}
	_, ok := sliceRange(ef.Bytes, ph.Offset, ph.Filesz)
	return ok
}

func shouldRenderSectionBytes(ef *ELFFile, sh SectionHeader) bool {
	if sh.Size == 0 {
		return false
	}
	if sh.Type == uint32(elf.SHT_NOBITS) {
		return false
	}
	_, ok := sliceRange(ef.Bytes, sh.Offset, sh.Size)
	return ok
}

func byteToken(data []byte, off int) string {
	if off == 0 {
		return "7f"
	}
	if off > 0 && off < 4 {
		return "&nbsp;" + string(data[off])
	}
	return fmt.Sprintf("%02x", data[off])
}

func writeStickyTable(b *strings.Builder, ef *ELFFile) {
	b.WriteString("    <table id='sticky_table' cellspacing='0'>\n")
	b.WriteString("      <tr>\n")
	b.WriteString("        <td id='desc'></td>\n")
	b.WriteString("        <td class='infotables'>\n")
	for _, ph := range ef.Segments {
		writeProgramHeaderTable(b, ph)
	}
	for _, sh := range ef.Sections {
		writeSectionHeaderTable(b, sh)
	}
	b.WriteString("        </td>\n")
	b.WriteString("        <td class='infotables'>\n")
	for _, ph := range ef.Segments {
		writeSegmentTable(b, ef, ph)
	}
	for _, sh := range ef.Sections {
		writeSectionTable(b, ef, sh)
	}
	b.WriteString("        </td>\n")
	b.WriteString("      </tr>\n")
	b.WriteString("    </table>\n")
}

