func writeSegmentTable(b *strings.Builder, ef *ELFFile, ph ProgramHeader) {
	b.WriteString(fmt.Sprintf("          <table class='conceal itable' id='info_segment%d'>\n", ph.Index))
	b.WriteString("          <th colspan='2' class='segment_itable'></th>\n")
	b.WriteString("            <tr> <td>Type:</td> <td>" + escapeHTML(programTypeName(ph.Type)) + "</td> </tr>\n")
	b.WriteString("            <tr> <td>Size in file:</td> <td>" + dataSizeSpan(ph.Filesz) + "</td> </tr>\n")
	b.WriteString("            <tr> <td>Size in memory:</td> <td>" + dataSizeSpan(ph.Memsz) + "</td> </tr>\n")

	if ph.Type == uint32(elf.PT_INTERP) {
		if blob, ok := sliceRange(ef.Bytes, ph.Offset, ph.Filesz); ok {
			b.WriteString("            <tr><td><br></td></tr>\n")
			b.WriteString("            <tr> <td>Interpreter:</td> <td>")
			b.WriteString(escapeHTML(trimCString(blob)))
			b.WriteString("</td> </tr>\n")
		}
	} else if ph.Type == uint32(elf.PT_NOTE) && len(ph.NoteEntries) > 0 {
		b.WriteString("            <tr><td><br></td></tr>\n")
		for i, note := range ph.NoteEntries {
			if i > 0 {
				b.WriteString("            <tr> <td><br></td> </tr>\n")
			}
			b.WriteString("            <tr> <td>Name:</td> <td>")
			b.WriteString(escapeHTML(note.Name))
			b.WriteString("</td> </tr>\n")
			b.WriteString(fmt.Sprintf("            <tr> <td>Type:</td> <td>0x%x</td> </tr>\n", note.Type))
			if note.Name == "GNU" && note.Type == 3 {
				b.WriteString("            <tr> <td>Build ID:</td> <td>")
				for _, by := range note.Desc {
					b.WriteString(fmt.Sprintf("%02x", by))
				}
				b.WriteString("</td> </tr>\n")
			} else {
				b.WriteString("            <tr> <td>Desc:</td> <td>")
				for _, by := range note.Desc {
					b.WriteString("<b>")
					b.WriteString(fmt.Sprintf("%02x", by))
					b.WriteString("</b> ")
				}
				b.WriteString("</td> </tr>\n")
			}
		}
	}

	b.WriteString("          </table>\n")
}

func writeSectionTable(b *strings.Builder, ef *ELFFile, sh SectionHeader) {
	b.WriteString(fmt.Sprintf("          <table class='conceal itable' id='info_section%d'>\n", sh.Index))
	b.WriteString("          <th colspan='2' class='section_itable'></th>\n")
	b.WriteString("            <tr> <td>Type:</td> <td>" + escapeHTML(sectionTypeName(sh.Type)) + "</td> </tr>\n")
	b.WriteString("            <tr> <td>Size:</td> <td>" + dataSizeSpan(sh.Size) + "</td> </tr>\n")

	if sh.Type == uint32(elf.SHT_STRTAB) {
		if blob, ok := ef.sectionData(sh); ok {
			b.WriteString("            <tr><td><br></td></tr>\n")
			b.WriteString("            <tr>\n")
			b.WriteString("              <td></td>\n")
			b.WriteString("              <td>\n")
			b.WriteString("                <div>\n")
			for _, entry := range stringTableEntries(blob) {
				b.WriteString("                  ")
				b.WriteString(escapeHTML(entry))
				b.WriteString("\n")
			}
			b.WriteString("                </div>\n")
			b.WriteString("              </td>\n")
			b.WriteString("            </tr>\n")
		}
	}

	b.WriteString("          </table>\n")
}

func writeHighlightScript(b *strings.Builder) {
